 MockHttpServletRequestBuilder as(MockHttpServletRequestBuilder r,String actor){return r.cookie(new Cookie("gl_session",actor));}
 MockHttpServletRequestBuilder body(MockHttpServletRequestBuilder r,String actor,Object b)throws Exception{return as(r,actor).header("Origin","http://localhost:3000").header("X-Requested-With","getlancer").contentType("application/json").content(json.writeValueAsString(b));}
 JsonNode ok(MockHttpServletRequestBuilder r)throws Exception{return json.readTree(mvc.perform(r).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());}
 Map<String,Object> terms(){return Map.of("engagementId",engagement,"title","Portal care","scope","Bug fixes and small approval workflow improvements.","terms","Includes bounded support. New features need a new agreement. Future billing may be cancelled.","amountMinor",10000,"requestsPerCycle",1,"responseHours",24,"totalCycles",12);}
 UUID draft()throws Exception{return UUID.fromString(ok(body(post("/api/v1/maintenance"),"care-seller",terms())).path("id").asText());}
 String base(UUID offer){return "/api/v1/maintenance/"+offer;}
 UUID accepted()throws Exception{UUID offer=draft();ok(body(post(base(offer)+"/send"),"care-seller",Map.of("consent",true)));String digest=ok(as(get(base(offer)),"care-buyer")).path("digest").asText();ok(body(post(base(offer)+"/accept"),"care-buyer",Map.of("consent",true,"digest",digest)));return offer;}
 JsonNode start(UUID offer)throws Exception{return ok(body(post(base(offer)+"/billing"),"care-buyer",Map.of("billingConsent",true)).header("Idempotency-Key",UUID.randomUUID()));}
 UUID paid()throws Exception{UUID offer=accepted();start(offer);fixture.paid=true;ok(body(post(base(offer)+"/billing/refresh"),"care-buyer",Map.of()));return offer;}
 String sign(String secret,String body)throws Exception{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return HexFormat.of().formatHex(mac.doFinal(body.getBytes(StandardCharsets.UTF_8)));}
 void automaticPass(){new MaintenanceBillingService(repository,access,payments,provider,security,json,transactions,true,true,MaintenanceFixture.WEBHOOK,true).pending();}
 void refundEvent(String event)throws Exception{String payload=json.writeValueAsString(Map.of("event","refund.created","payload",Map.of("refund",Map.of("entity",Map.of("id",MaintenanceFixture.REFUND,"payment_id",MaintenanceFixture.PAYMENT)))));ok(post("/api/v1/maintenance/razorpay/webhook").contentType("application/json").content(payload).header("X-Razorpay-Event-Id",event).header("X-Razorpay-Signature",sign(MaintenanceFixture.WEBHOOK,payload)));}
 String operator(UUID id,String action){return "/api/v1/admin/maintenance/"+id+"/"+action;}
 UUID boundPlanWithoutSubscription()throws Exception{
  UUID offer=accepted();fixture.blockPlan=true;var pool=Executors.newSingleThreadExecutor();try{var start=pool.submit(()->mvc.perform(body(post(base(offer)+"/billing"),"care-buyer",Map.of("billingConsent",true)).header("Idempotency-Key",UUID.randomUUID())).andReturn().getResponse().getStatus());assertTrue(fixture.entered.await(3,TimeUnit.SECONDS));db.update("UPDATE developer_profiles SET approval_status='SUSPENDED' WHERE user_id=?",seller);fixture.release.countDown();assertEquals(409,start.get(8,TimeUnit.SECONDS));}finally{fixture.release.countDown();pool.shutdownNow();fixture.blockPlan=false;}
  assertEquals(1,fixture.plans.get());assertEquals(0,fixture.subscriptions.get());assertEquals("CONFIRMED",db.queryForObject("SELECT plan_state FROM maintenance_subscriptions",String.class));assertEquals("NOT_CREATED",db.queryForObject("SELECT subscription_state FROM maintenance_subscriptions",String.class));db.update("UPDATE developer_profiles SET approval_status='APPROVED' WHERE user_id=?",seller);return db.queryForObject("SELECT id FROM maintenance_subscriptions",UUID.class);
 }
 void noSubscriptionRetry(UUID offer,UUID id,String state)throws Exception{
  assertEquals("CONFIRMED",db.queryForObject("SELECT plan_state FROM maintenance_subscriptions WHERE id=?",String.class,id));assertEquals(MaintenanceFixture.PLAN,db.queryForObject("SELECT provider_plan_id FROM maintenance_subscriptions WHERE id=?",String.class,id));assertEquals("SUBSCRIPTION",db.queryForObject("SELECT creation_step FROM maintenance_subscriptions WHERE id=?",String.class,id));assertEquals(state,db.queryForObject("SELECT subscription_state FROM maintenance_subscriptions WHERE id=?",String.class,id));assertNull(db.queryForObject("SELECT provider_subscription_id FROM maintenance_subscriptions WHERE id=?",String.class,id));UUID key=db.queryForObject("SELECT request_key FROM maintenance_subscriptions WHERE id=?",UUID.class,id);ok(body(post(base(offer)+"/billing"),"care-buyer",Map.of("billingConsent",true)).header("Idempotency-Key",key));start(offer);mvc.perform(body(post(operator(id,"resume-subscription")),"care-admin",Map.of("reason","Previously attempted subscription creation must never be retried."))).andExpect(status().isConflict());assertEquals(state,db.queryForObject("SELECT subscription_state FROM maintenance_subscriptions WHERE id=?",String.class,id));assertTrue(fixture.committedSubscription);assertEquals(1,fixture.plans.get());assertEquals(1,fixture.subscriptions.get());
 }
 void recoverCreatedSubscription(UUID id)throws Exception{
  ok(body(post(operator(id,"bind-subscription")),"care-admin",Map.of("providerId",MaintenanceFixture.SUB,"reason","Verified exact provider subscription identity and frozen agreement facts.")));assertEquals("CONFIRMED",db.queryForObject("SELECT subscription_state FROM maintenance_subscriptions WHERE id=?",String.class,id));assertEquals("CONFIRMED",db.queryForObject("SELECT plan_state FROM maintenance_subscriptions WHERE id=?",String.class,id));assertEquals(MaintenanceFixture.SUB,db.queryForObject("SELECT provider_subscription_id FROM maintenance_subscriptions WHERE id=?",String.class,id));assertEquals(1,fixture.plans.get());assertEquals(1,fixture.subscriptions.get());
 }
 @Test void currentPartiesConsentDigestAndFrozenTermsAreRequired()throws Exception{mvc.perform(body(post("/api/v1/maintenance"),"care-outsider",terms())).andExpect(status().isNotFound());UUID offer=draft();mvc.perform(body(post(base(offer)+"/send"),"care-seller",Map.of())).andExpect(status().isBadRequest());ok(body(post(base(offer)+"/send"),"care-seller",Map.of("consent",true)));mvc.perform(body(post(base(offer)+"/accept"),"care-buyer",Map.of("consent",true,"digest","stale"))).andExpect(status().isConflict());db.update("UPDATE developer_profiles SET approval_status='SUSPENDED' WHERE user_id=?",seller);String digest=db.queryForObject("SELECT digest FROM maintenance_offers WHERE id=?",String.class,offer);mvc.perform(body(post(base(offer)+"/accept"),"care-buyer",Map.of("consent",true,"digest",digest))).andExpect(status().isConflict());assertThrows(DataAccessException.class,()->db.update("UPDATE maintenance_offers SET amount_minor=11000 WHERE id=?",offer));}
 @Test void reservationsCommitBeforeEachHttpPostAndRetriesDoNotDuplicate()throws Exception{UUID offer=accepted();mvc.perform(body(post(base(offer)+"/billing"),"care-buyer",Map.of()).header("Idempotency-Key",UUID.randomUUID())).andExpect(status().isBadRequest());JsonNode checkout=start(offer);start(offer);assertEquals(1,fixture.plans.get());assertEquals(1,fixture.subscriptions.get());assertTrue(fixture.committedPlan);assertTrue(fixture.committedSubscription);assertFalse(ok(as(get(base(offer)),"care-buyer")).path("entitlement").path("available").asBoolean());fixture.paid=true;ok(body(post(base(offer)+"/billing/refresh"),"care-buyer",Map.of()));assertTrue(fixture.committedTransfer);assertEquals(1,fixture.transfers.get());assertTrue(ok(as(get(base(offer)),"care-buyer")).path("entitlement").path("available").asBoolean());ok(body(post(base(offer)+"/billing/refresh"),"care-buyer",Map.of()));assertEquals(1,fixture.transfers.get());}
 @Test void checkoutUsesSubscriptionSignatureAndNeverGrantsFromActivationAlone()throws Exception{UUID offer=accepted();start(offer);String signature=sign(MaintenanceFixture.SECRET,MaintenanceFixture.PAYMENT+"|"+MaintenanceFixture.SUB);var b=Map.of("razorpay_subscription_id",MaintenanceFixture.SUB,"razorpay_payment_id",MaintenanceFixture.PAYMENT,"razorpay_signature",signature);ok(body(post(base(offer)+"/billing/confirm"),"care-buyer",b));assertFalse(ok(as(get(base(offer)),"care-buyer")).path("entitlement").path("available").asBoolean());var wrong=new HashMap<String,Object>(b);wrong.put("razorpay_signature",sign(MaintenanceFixture.SECRET,MaintenanceFixture.SUB+"|"+MaintenanceFixture.PAYMENT));mvc.perform(body(post(base(offer)+"/billing/confirm"),"care-buyer",wrong)).andExpect(status().isBadRequest());}
 @Test void unknownPlanBlocksRetriesAndMfaRecoveryVerifiesNotes()throws Exception{UUID offer=accepted();fixture.unknownPlan=true;mvc.perform(body(post(base(offer)+"/billing"),"care-buyer",Map.of("billingConsent",true)).header("Idempotency-Key",UUID.randomUUID())).andExpect(status().isBadGateway());start(offer);assertEquals(1,fixture.plans.get());assertEquals(0,fixture.subscriptions.get());UUID id=db.queryForObject("SELECT id FROM maintenance_subscriptions",UUID.class);mvc.perform(body(post("/api/v1/admin/maintenance/"+id+"/bind-plan"),"care-buyer",Map.of("providerId",MaintenanceFixture.PLAN,"reason","Verified matching provider plan notes."))).andExpect(status().isForbidden());ok(body(post("/api/v1/admin/maintenance/"+id+"/bind-plan"),"care-admin",Map.of("providerId",MaintenanceFixture.PLAN,"reason","Verified matching provider plan notes.")));assertEquals(1,fixture.subscriptions.get());}
 @Test void uncertainRoutingCannotBeRepeatedAndRequiresExactOperatorBinding()throws Exception{UUID offer=accepted();start(offer);fixture.paid=true;fixture.unknownTransfer=true;ok(body(post(base(offer)+"/billing/refresh"),"care-buyer",Map.of()));ok(body(post(base(offer)+"/billing/refresh"),"care-buyer",Map.of()));assertEquals(1,fixture.transfers.get());assertFalse(ok(as(get(base(offer)),"care-buyer")).path("entitlement").path("available").asBoolean());UUID subscription=db.queryForObject("SELECT id FROM maintenance_subscriptions",UUID.class),period=db.queryForObject("SELECT id FROM maintenance_periods",UUID.class);ok(body(post("/api/v1/admin/maintenance/"+subscription+"/bind-transfer"),"care-admin",Map.of("providerId",MaintenanceFixture.TRANSFER,"periodId",period,"reason","Verified one exact invoice transfer in the provider.")));assertEquals(1,fixture.transfers.get());assertTrue(ok(as(get(base(offer)),"care-buyer")).path("entitlement").path("available").asBoolean());}
 @Test void invoiceMismatchRefundStatusPendingRefundAndMonotonicRefundsHoldService()throws Exception{UUID offer=accepted();start(offer);fixture.paid=true;fixture.wrongInvoice=true;mvc.perform(body(post(base(offer)+"/billing/refresh"),"care-buyer",Map.of())).andExpect(status().isConflict());assertEquals(0,fixture.transfers.get());fixture.wrongInvoice=false;fixture.invalidRefundStatus=true;mvc.perform(body(post(base(offer)+"/billing/refresh"),"care-buyer",Map.of())).andExpect(status().isConflict());fixture.invalidRefundStatus=false;fixture.pendingRefund=true;ok(body(post(base(offer)+"/billing/refresh"),"care-buyer",Map.of()));assertEquals(0,fixture.transfers.get());fixture.pendingRefund=false;fixture.refunded=1000;ok(body(post(base(offer)+"/billing/refresh"),"care-buyer",Map.of()));fixture.refunded=0;ok(body(post(base(offer)+"/billing/refresh"),"care-buyer",Map.of()));assertEquals(1000,db.queryForObject("SELECT refunded_minor FROM maintenance_periods",Long.class));assertEquals(1,db.queryForObject("SELECT count(*) FROM maintenance_refunds",Integer.class));assertEquals(1000,db.queryForObject("SELECT sum(amount_minor) FROM maintenance_ledger WHERE kind='REFUND'",Long.class));assertFalse(ok(as(get(base(offer)),"care-buyer")).path("entitlement").path("available").asBoolean());}
 @Test void signedDisputeIsFetchedByExactIdEvenBeforeAccountListShowsItAndDeduped()throws Exception{UUID offer=paid();String payload=json.writeValueAsString(Map.of("event","payment.dispute.created","payload",Map.of("dispute",Map.of("entity",Map.of("id",MaintenanceFixture.DISPUTE,"payment_id",MaintenanceFixture.PAYMENT)))));var hook=post("/api/v1/maintenance/razorpay/webhook").contentType("application/json").content(payload).header("X-Razorpay-Event-Id","care-event-1").header("X-Razorpay-Signature",sign(MaintenanceFixture.WEBHOOK,payload));ok(hook);ok(hook);assertEquals(1,db.queryForObject("SELECT count(*) FROM maintenance_webhook_events",Integer.class));assertFalse(ok(as(get(base(offer)),"care-buyer")).path("entitlement").path("available").asBoolean());fixture.raiseDispute=true;fixture.listDispute=false;ok(body(post(base(offer)+"/billing/refresh"),"care-buyer",Map.of()));assertEquals(1,db.queryForObject("SELECT count(*) FROM maintenance_provider_disputes WHERE status='open'",Integer.class));assertFalse(ok(as(get(base(offer)),"care-buyer")).path("entitlement").path("available").asBoolean());fixture.disputeStatus="won";ok(body(post(base(offer)+"/billing/refresh"),"care-buyer",Map.of()));assertFalse(ok(as(get(base(offer)),"care-buyer")).path("entitlement").path("available").asBoolean());String other=payload+" ";mvc.perform(post("/api/v1/maintenance/razorpay/webhook").content(other).header("X-Razorpay-Event-Id","care-event-1").header("X-Razorpay-Signature",sign(MaintenanceFixture.WEBHOOK,other))).andExpect(status().isConflict());assertThrows(DataAccessException.class,()->db.update("DELETE FROM maintenance_webhook_events"));}
 @Test void quotaStatesAndLateOriginalFinancialHoldAreEnforced()throws Exception{UUID offer=paid();var support=Map.of("title","Approval notification","description","Correct the notification for the second approval reviewer.");UUID key=UUID.randomUUID();String id=ok(body(post(base(offer)+"/requests"),"care-buyer",support).header("Idempotency-Key",key)).path("id").asText();assertEquals(id,ok(body(post(base(offer)+"/requests"),"care-buyer",support).header("Idempotency-Key",key)).path("id").asText());mvc.perform(body(post(base(offer)+"/requests"),"care-buyer",support).header("Idempotency-Key",UUID.randomUUID())).andExpect(status().isConflict());mvc.perform(body(post(base(offer)+"/requests/"+id+"/start"),"care-buyer",Map.of())).andExpect(status().isForbidden());ok(body(post(base(offer)+"/requests/"+id+"/start"),"care-seller",Map.of()));ok(body(post(base(offer)+"/requests/"+id+"/submit"),"care-seller",Map.of("deliveryNote","Corrected and verified both reviewer notifications.")));ok(body(post(base(offer)+"/requests/"+id+"/request-revision"),"care-buyer",Map.of("reason","Please include the third reviewer's notification too.")));ok(body(post(base(offer)+"/requests/"+id+"/cancel"),"care-buyer",Map.of()));assertEquals(0,ok(as(get(base(offer)),"care-buyer")).path("entitlement").path("remainingRequests").asInt());assertThrows(DataAccessException.class,()->db.update("DELETE FROM maintenance_requests"));db.update("UPDATE payment_attempts SET refunded_minor=1000 WHERE id=?",originalPayment);assertFalse(ok(as(get(base(offer)),"care-buyer")).path("entitlement").path("available").asBoolean());mvc.perform(body(post(base(offer)+"/requests"),"care-buyer",support).header("Idempotency-Key",UUID.randomUUID())).andExpect(status().isConflict());}
