  UUID offer=accepted();start(offer);fixture.cancelUncertain=true;fixture.cancelStaysActive=true;mvc.perform(body(post(base(offer)+"/billing/cancel"),"care-buyer",Map.of())).andExpect(status().isBadGateway());assertEquals("UNKNOWN",db.queryForObject("SELECT cancel_state FROM maintenance_subscriptions",String.class));UUID first=db.queryForObject("SELECT id FROM maintenance_subscriptions",UUID.class);db.update("UPDATE maintenance_subscriptions SET updated_at=now()-interval '6 days' WHERE id=?",first);UUID sixth=null;
